SELECT a.id,a.`title`,a.`editTime`,a.`pageView`,a.`state`,a.`cateName`,a.`nickname` FROM article a

    WHERE a.state=#{state}


    WHERE a.state=1




            and a.state=#{state}


            and a.state=1

        AND title LIKE concat('%',#{keywords},'%')


ORDER BY a.editTime DESC limit #{start},#{count};

SELECT a.id,a.`title`,a.`editTime`,a.`pageView`,a.`state`,a.`cateName`,a.`nickname` FROM article a WHERE a.state=1

    AND title LIKE concat('%',#{keywords},'%')

ORDER BY a.editTime DESC limit #{start},#{count};

SELECT count(*) FROM article


        AND state=#{state}


        AND title LIKE concat('%',#{keywords},'%')
